const prims = ['string','number','boolean','date','uuid','decimal'];
// `effectiveAttributes` is provided by the engine when iterating entities —
// it folds in attributes inherited via `extends` and composed via interface
// `implements`. Falls back to own `attributes` when the engine doesn't surface
// it (loop-logic sources, custom iteration).
const attrs = (typeof effectiveAttributes !== 'undefined' && effectiveAttributes) || attributes || [];
const types = attrs.filter(function (a) { return a.aggregation !== 'none'; }).map(function (a) { return a.type; }).filter(function (t) { return prims.indexOf(t) === -1; });
nonPrimitives = Array.from(new Set(types));

const primMap = { string: 'z.string()', number: 'z.number()', boolean: 'z.boolean()', date: 'z.date()', uuid: 'z.string().uuid()', decimal: 'z.number()' };
function zodFor(a) {
  let base;
  // aggregation === 'none' stores the referent's UUID, not an embedded copy.
  // Composite (or absent) embeds the target's Zod schema. Primitive types
  // always go through primMap regardless of aggregation (it's forbidden on
  // primitives by AttributeSchema's validation).
  if (a.aggregation === 'none' && !(a.type in primMap)) {
    base = 'z.string().uuid()';
  } else {
    base = primMap[a.type] || (pascalCase(a.type) + 'Schema');
  }
  if (a.multiValue) { base += '.array()'; }
  if (!a.required) { base += '.optional()'; }
  if (a.description) { base += '.describe("' + a.description + '")'; }
  return base;
}

// Prefer the engine-provided effective attribute list (folds extends + interface implements).
const sourceAttrs = (typeof effectiveAttributes !== 'undefined' && effectiveAttributes) || attributes || [];
attrSpecs = sourceAttrs.map(function (a) {
  return { camel: camelCase(a.name), zodType: zodFor(a) };
});

import { z } from 'zod'
{{#each nonPrimitives}}
import { {{pascalCase this}}Schema } from './{{pascalCase this}}Schema';
{{/each}}
